def scenario(grid,tracks,prod,q=5,condition='screened'):
    return r[(r.grid_km==grid)&(r.tracks==tracks)&(r['product']==prod)&(r.new_hubs==q)&(r.condition==condition)].iloc[0]
def sites(grid):
    return z[(z.grid_km==grid)&(z.tracks==False)&(z['product']=='WorldPop')&(z.new_hubs==5)&(z.condition=='screened')].reset_index(drop=True)

